package com.chesspulseai.exception;
import com.chesspulseai.dto.ApiError; import jakarta.validation.*; import java.time.*; import java.util.*; import org.slf4j.*; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class GlobalExceptionHandler { private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class); private ResponseEntity<ApiError> error(HttpStatus status,String code,String message){return ResponseEntity.status(status).body(new ApiError(Instant.now(),status.value(),code,message,Map.of()));} @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<ApiError> missing(ResourceNotFoundException e){return error(HttpStatus.NOT_FOUND,"NOT_FOUND",e.getMessage());} @ExceptionHandler(IllegalChessMoveException.class) ResponseEntity<ApiError> illegal(IllegalChessMoveException e){return error(HttpStatus.UNPROCESSABLE_ENTITY,"ILLEGAL_MOVE",e.getMessage());} @ExceptionHandler(EngineUnavailableException.class) ResponseEntity<ApiError> engine(EngineUnavailableException e){return error(HttpStatus.SERVICE_UNAVAILABLE,"ENGINE_UNAVAILABLE",e.getMessage());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException e){Map<String,String> fields=new HashMap<>();e.getBindingResult().getFieldErrors().forEach(x->fields.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(new ApiError(Instant.now(),400,"VALIDATION_FAILED","Request validation failed",fields));} @ExceptionHandler(Exception.class) ResponseEntity<ApiError> unknown(Exception e){log.error("Unhandled API exception",e);return error(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_ERROR","An unexpected error occurred");}}
